<script lang="ts">
  import { onMount } from 'svelte';
  import { invoke } from '@tauri-apps/api/core';
  import type { AssociationSnapshot } from './applications';
  let mimeType=$state('text/plain'),snapshot=$state<AssociationSnapshot|null>(null),chosen=$state(''),types=$state<string[]>([]),busy=$state(false),error=$state(''),message=$state('');
  let alive=true,sequence=0;
  const common=[['text/plain','Plain text'],['application/pdf','PDF documents'],['inode/directory','Folders'],['x-scheme-handler/http','Web links (HTTP)'],['x-scheme-handler/https','Secure web links (HTTPS)'],['x-scheme-handler/mailto','Email links'],['text/html','HTML documents'],['image/png','PNG images'],['image/jpeg','JPEG images']];
  async function reload(){const token=++sequence;busy=true;error='';message='';try{const next=await invoke<AssociationSnapshot>('get_file_association',{mimeType});if(alive&&sequence===token){snapshot=next;chosen=next.current??'';mimeType=next.mime_type;}}catch(cause){if(alive&&sequence===token)error=String(cause);}finally{if(alive&&sequence===token)busy=false;}}
  async function apply(){if(!snapshot||busy||!chosen)return;const token=++sequence;busy=true;error='';message='';try{const next=await invoke<{snapshot:AssociationSnapshot;message:string}>('set_file_association',{mimeType:snapshot.mime_type,expected:snapshot.current,version:snapshot.version,desktopId:chosen});if(alive&&sequence===token){snapshot=next.snapshot;chosen=snapshot.current??'';message=next.message;}}catch(cause){if(alive&&sequence===token)error=String(cause);}finally{if(alive&&sequence===token)busy=false;}}
  onMount(()=>{void reload();void invoke<string[]>('get_application_content_types').then(next=>{if(alive)types=next;}).catch(()=>{});return()=>{alive=false;sequence++;};});
</script>
<section class="section"><h2>File and link associations</h2><p class="description">Choose installed desktop applications for files and links opened through your desktop. FocalDesk’s launch commands are managed separately in Defaults.</p>{#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if message}<div class="notice success" role="status">{message}</div>{/if}<fieldset disabled={busy}><legend class="sr-only">File association controls</legend><div class="settings-card"><div class="setting-row"><label for="association-common">Common file and link types</label><select id="association-common" value={mimeType} onchange={event=>{mimeType=event.currentTarget.value;void reload();}}>{#if !common.some(([value])=>value===mimeType)}<option value={mimeType}>Custom type</option>{/if}{#each common as [value,label]}<option {value}>{label}</option>{/each}</select></div><div class="setting-row"><div><label for="association-type">MIME type or URL scheme</label><p>For example application/pdf or x-scheme-handler/https.</p></div><input id="association-type" type="text" list="registered-content-types" maxlength="255" bind:value={mimeType} onkeydown={event=>{if(event.key==='Enter')void reload();}} /><datalist id="registered-content-types">{#each types.filter(type=>type.includes(mimeType.toLowerCase())).slice(0,100) as type}<option value={type}></option>{/each}</datalist><button class="quiet" onclick={reload}>Load association</button></div></div></fieldset>
{#if busy}<p class="description" role="status">Reading or updating desktop associations…</p>{/if}
{#if snapshot}<section class="association-details"><h2>{snapshot.description}</h2><p class="type-label">{snapshot.mime_type}</p><div class="settings-card"><div class="setting-row"><div><strong>Current default</strong><p>{snapshot.applications.find(app=>app.id===snapshot?.current)?.name??snapshot.current??'No default available'}</p></div></div><div class="setting-row"><div><label for="association-app">Open with</label><p>Recommended applications advertise support for this type.</p></div><select id="association-app" disabled={busy} bind:value={chosen}><option value="">Choose an installed application</option>{#if snapshot.current&&!snapshot.applications.some(app=>app.id===snapshot?.current)}<option value={snapshot.current}>{snapshot.current} (current, unavailable)</option>{/if}{#each snapshot.applications as app}<option value={app.id}>{app.name}{app.recommended?' · recommended':''}</option>{/each}</select></div>{#if chosen}<div class="setting-row"><p>{snapshot.applications.find(app=>app.id===chosen)?.description}<br />{chosen}</p></div>{/if}</div><div class="association-actions"><button class="quiet" disabled={busy} onclick={reload}>Reload association</button><button class="primary" disabled={busy||!chosen||chosen===snapshot.current||mimeType.trim().toLowerCase()!==snapshot.mime_type||!snapshot.applications.some(app=>app.id===chosen)} onclick={apply}>Set default for this type</button></div><p class="description">This updates the desktop association for this one type. Future opens use the chosen application.</p></section>{/if}</section>
<style>fieldset{padding:0;margin:0;border:0;min-width:0}.description{font-size:12px;color:var(--fd-text-muted);line-height:1.8;margin:12px 0 18px}input,select{font:inherit;font-size:12px;border:1px solid var(--fd-border);border-radius:8px;padding:10px;background:var(--fd-surface);color:var(--fd-text);max-width:340px;width:45%}.association-details{margin-top:25px}.type-label{font:11px ui-monospace,monospace;color:var(--fd-text-muted);margin:10px 0 18px}.association-actions{display:flex;justify-content:flex-end;gap:10px;margin:20px 0}.primary{background:var(--fd-accent);color:white;padding:10px 14px;border-radius:8px;font-size:12px}strong{font-size:13px;font-weight:600}.setting-row>div{min-width:0;overflow-wrap:anywhere}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:600px){input,select{width:100%;max-width:none}}</style>
